import type { SupabaseClient } from "@supabase/supabase-js";
import { toRangeTimestamps, type ReportDateRange } from "./shared";

export type ReconciliationRow = {
  shift_id: string;
  store_id: string;
  till_id: string;
  till_label: string;
  cashier_id: string;
  cashier_name: string;
  opened_at: string;
  closed_at: string;
  opening_float: number;
  cash_counted: number | null;
  /** Cash the system expects based on synced sale/refund tenders for this shift. */
  system_cash: number;
  /** `cash_counted - system_cash - opening_float`, generated by the `shifts` projection. */
  over_short: number | null;
};

export type ReconciliationReport = {
  shifts: ReconciliationRow[];
};

export type ReconciliationReportParams = {
  range: ReportDateRange;
  storeId?: string;
};

type ShiftRow = {
  shift_id: string;
  store_id: string;
  till_id: string;
  cashier_id: string;
  opened_at: string;
  closed_at: string | null;
  opening_float: number;
  cash_counted: number | null;
  system_cash: number;
  over_short: number | null;
  status: string;
};

// FR-032: till reconciliation comparing cash-up figures (`cash_counted`)
// against system totals (`system_cash`) per shift. Only closed shifts have
// a meaningful `over_short` (the `shifts` projection's generated column is
// null until `cash_counted` is recorded at cash-up).
export async function loadReconciliationReport(
  supabase: SupabaseClient,
  params: ReconciliationReportParams,
): Promise<ReconciliationReport> {
  const { fromTs, toTs } = toRangeTimestamps(params.range);

  let shiftsQuery = supabase
    .from("shifts")
    .select("shift_id, store_id, till_id, cashier_id, opened_at, closed_at, opening_float, cash_counted, system_cash, over_short, status")
    .eq("status", "closed")
    .gte("closed_at", fromTs)
    .lt("closed_at", toTs);
  if (params.storeId !== undefined) shiftsQuery = shiftsQuery.eq("store_id", params.storeId);

  const shiftsResult = await shiftsQuery;
  if (shiftsResult.error !== null) throw new Error(`Failed to load shifts: ${shiftsResult.error.message}`);
  const shifts: ShiftRow[] = shiftsResult.data ?? [];

  const tillIds = [...new Set(shifts.map((shift) => shift.till_id))];
  const cashierIds = [...new Set(shifts.map((shift) => shift.cashier_id))];

  const [tillsResult, usersResult] = await Promise.all([
    tillIds.length > 0
      ? supabase.from("tills").select("till_id, label").in("till_id", tillIds)
      : Promise.resolve({ data: [], error: null }),
    cashierIds.length > 0
      ? supabase.from("users").select("user_id, full_name").in("user_id", cashierIds)
      : Promise.resolve({ data: [], error: null }),
  ]);

  if (tillsResult.error !== null) throw new Error(`Failed to load till labels: ${tillsResult.error.message}`);
  if (usersResult.error !== null) throw new Error(`Failed to load cashier names: ${usersResult.error.message}`);

  const tillRows: { till_id: string; label: string }[] = tillsResult.data ?? [];
  const userRows: { user_id: string; full_name: string }[] = usersResult.data ?? [];
  const tillLabelById = new Map(tillRows.map((till) => [till.till_id, till.label]));
  const cashierNameById = new Map(userRows.map((user) => [user.user_id, user.full_name]));

  const rows: ReconciliationRow[] = shifts
    .filter((shift): shift is ShiftRow & { closed_at: string } => shift.closed_at !== null)
    .map((shift) => ({
      shift_id: shift.shift_id,
      store_id: shift.store_id,
      till_id: shift.till_id,
      till_label: tillLabelById.get(shift.till_id) ?? shift.till_id,
      cashier_id: shift.cashier_id,
      cashier_name: cashierNameById.get(shift.cashier_id) ?? shift.cashier_id,
      opened_at: shift.opened_at,
      closed_at: shift.closed_at,
      opening_float: shift.opening_float,
      cash_counted: shift.cash_counted,
      system_cash: shift.system_cash,
      over_short: shift.over_short,
    }))
    .sort((a, b) => b.closed_at.localeCompare(a.closed_at));

  return { shifts: rows };
}
